{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "/spec/cellarpack-v1.schema.json",
  "title": "Tin to Cellar CellarPack v1 manifest",
  "type": "object",
  "required": ["format", "schemaVersion", "packId", "createdAt", "generator", "labels", "assets"],
  "properties": {
    "format": { "const": "tin-to-cellar/cellarpack" },
    "schemaVersion": { "type": "string", "pattern": "^1\\.[0-9]+\\.[0-9]+$" },
    "packId": {
      "type": "string",
      "pattern": "^urn:uuid:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"
    },
    "createdAt": { "$ref": "#/$defs/dateTime" },
    "title": { "type": "string", "minLength": 1, "maxLength": 120 },
    "description": { "type": "string", "maxLength": 2000 },
    "locale": { "type": "string", "minLength": 2, "maxLength": 35 },
    "generator": { "$ref": "#/$defs/generator" },
    "labels": {
      "type": "array",
      "minItems": 1,
      "maxItems": 100,
      "items": { "$ref": "#/$defs/label" }
    },
    "assets": {
      "type": "object",
      "minProperties": 1,
      "maxProperties": 300,
      "propertyNames": { "$ref": "#/$defs/canonicalId" },
      "additionalProperties": { "$ref": "#/$defs/artworkAsset" }
    },
    "defaultPrintIntent": {
      "type": "object",
      "required": ["sheetProfileId"],
      "properties": {
        "sheetProfileId": { "type": "string", "minLength": 3, "maxLength": 160 },
        "labelQuantityMode": { "enum": ["one-each", "fill-sheet"] }
      },
      "additionalProperties": true
    },
    "customSheetProfiles": {
      "type": "array",
      "maxItems": 25,
      "items": {
        "type": "object",
        "required": ["id", "path"],
        "properties": {
          "id": { "type": "string", "minLength": 3, "maxLength": 160 },
          "path": { "type": "string", "pattern": "^sheet-profiles/[A-Za-z0-9._-]+\\.json$", "maxLength": 240 }
        },
        "additionalProperties": true
      }
    },
    "extensions": { "type": "object" }
  },
  "additionalProperties": true,
  "$defs": {
    "canonicalId": {
      "type": "string",
      "pattern": "^[a-z0-9]+(?:-[a-z0-9]+)*$",
      "maxLength": 120
    },
    "dateTime": {
      "type": "string",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(?:\\.[0-9]+)?Z$"
    },
    "generator": {
      "type": "object",
      "required": ["name", "version"],
      "properties": {
        "name": { "type": "string", "minLength": 1, "maxLength": 160 },
        "version": { "type": "string", "minLength": 1, "maxLength": 80 },
        "model": { "type": "string", "maxLength": 160 },
        "workflowUrl": { "type": "string", "pattern": "^https?://", "maxLength": 2048 }
      },
      "additionalProperties": true
    },
    "physicalSize": {
      "type": "object",
      "required": ["width", "height", "unit"],
      "properties": {
        "width": { "type": "number", "exclusiveMinimum": 0, "maximum": 1000 },
        "height": { "type": "number", "exclusiveMinimum": 0, "maximum": 1000 },
        "unit": { "enum": ["in", "mm"] }
      },
      "additionalProperties": true
    },
    "physicalInsets": {
      "type": "object",
      "required": ["top", "right", "bottom", "left", "unit"],
      "properties": {
        "top": { "type": "number", "minimum": 0, "maximum": 100 },
        "right": { "type": "number", "minimum": 0, "maximum": 100 },
        "bottom": { "type": "number", "minimum": 0, "maximum": 100 },
        "left": { "type": "number", "minimum": 0, "maximum": 100 },
        "unit": { "enum": ["in", "mm"] }
      },
      "additionalProperties": true
    },
    "surface": {
      "type": "object",
      "required": ["shape", "finishedSize", "bleed", "safeInset"],
      "properties": {
        "shape": { "enum": ["circle", "oval", "square", "rectangle", "rounded-rectangle", "custom"] },
        "finishedSize": { "$ref": "#/$defs/physicalSize" },
        "bleed": { "$ref": "#/$defs/physicalInsets" },
        "safeInset": { "$ref": "#/$defs/physicalInsets" },
        "cornerRadius": { "type": "number", "minimum": 0 }
      },
      "additionalProperties": true
    },
    "writeInArea": {
      "type": "object",
      "required": ["id", "purpose", "geometry", "background", "overlay"],
      "properties": {
        "id": { "$ref": "#/$defs/canonicalId" },
        "purpose": { "const": "jarred-date" },
        "geometry": {
          "type": "object",
          "required": ["shape", "x", "y", "width", "height"],
          "properties": {
            "shape": { "enum": ["rectangle", "rounded-rectangle", "oval"] },
            "x": { "type": "number", "minimum": 0, "maximum": 1 },
            "y": { "type": "number", "minimum": 0, "maximum": 1 },
            "width": { "type": "number", "exclusiveMinimum": 0, "maximum": 1 },
            "height": { "type": "number", "exclusiveMinimum": 0, "maximum": 1 },
            "cornerRadius": { "type": "number", "minimum": 0, "maximum": 0.5 },
            "rotationDegrees": { "const": 0 }
          },
          "additionalProperties": true
        },
        "background": {
          "type": "object",
          "required": ["integratedInArtwork"],
          "properties": {
            "integratedInArtwork": { "type": "boolean" },
            "appearance": { "type": "string", "maxLength": 500 },
            "minimumContrastWithInk": { "enum": ["high", "medium", "low"] }
          },
          "additionalProperties": true
        },
        "overlay": {
          "type": "object",
          "required": ["mode"],
          "properties": {
            "mode": { "const": "blank" }
          },
          "additionalProperties": false
        }
      },
      "additionalProperties": true
    },
    "webSource": {
      "type": "object",
      "required": ["id", "type", "role", "url", "title", "retrievedAt"],
      "properties": {
        "id": { "$ref": "#/$defs/canonicalId" },
        "type": { "const": "web" },
        "role": { "$ref": "#/$defs/sourceRole" },
        "url": { "type": "string", "pattern": "^https?://", "maxLength": 2048 },
        "title": { "type": "string", "minLength": 1, "maxLength": 500 },
        "retrievedAt": { "$ref": "#/$defs/dateTime" },
        "publisher": { "type": "string", "maxLength": 300 },
        "notes": { "type": "string", "maxLength": 1000 }
      },
      "additionalProperties": true
    },
    "userSource": {
      "type": "object",
      "required": ["id", "type", "role", "description", "receivedAt"],
      "properties": {
        "id": { "$ref": "#/$defs/canonicalId" },
        "type": { "const": "user-provided" },
        "role": { "$ref": "#/$defs/sourceRole" },
        "description": { "type": "string", "minLength": 1, "maxLength": 1000 },
        "receivedAt": { "$ref": "#/$defs/dateTime" },
        "originalFilename": { "type": "string", "maxLength": 240, "pattern": "^[^/\\\\]+$" },
        "notes": { "type": "string", "maxLength": 1000 }
      },
      "additionalProperties": true
    },
    "sourceRole": {
      "enum": ["package-appearance", "variant-identification", "historical-context", "user-inspiration"]
    },
    "research": {
      "type": "object",
      "required": ["status", "observedPackage", "visualAnalysis", "sources", "adaptationSummary"],
      "properties": {
        "status": { "enum": ["complete", "limited"] },
        "observedPackage": {
          "type": "object",
          "required": ["format", "variant", "variantDateOrEdition"],
          "properties": {
            "format": { "type": "string", "minLength": 1, "maxLength": 300 },
            "variant": { "type": "string", "minLength": 1, "maxLength": 1000 },
            "variantDateOrEdition": { "type": "string", "minLength": 1, "maxLength": 300 }
          },
          "additionalProperties": true
        },
        "visualAnalysis": {
          "type": "object",
          "required": ["palette", "motifs", "border", "typography", "hierarchy", "style"],
          "properties": {
            "palette": { "type": "array", "minItems": 1, "maxItems": 20, "items": { "type": "string", "minLength": 1, "maxLength": 120 } },
            "motifs": { "type": "array", "maxItems": 30, "items": { "type": "string", "minLength": 1, "maxLength": 300 } },
            "border": { "type": "string", "minLength": 1, "maxLength": 1000 },
            "typography": { "type": "string", "minLength": 1, "maxLength": 1000 },
            "hierarchy": { "type": "string", "minLength": 1, "maxLength": 1000 },
            "style": { "type": "string", "minLength": 1, "maxLength": 1000 }
          },
          "additionalProperties": true
        },
        "sources": {
          "type": "array",
          "minItems": 1,
          "maxItems": 20,
          "items": { "oneOf": [{ "$ref": "#/$defs/webSource" }, { "$ref": "#/$defs/userSource" }] }
        },
        "adaptationSummary": { "type": "string", "minLength": 1, "maxLength": 2000 },
        "limitations": { "type": "string", "maxLength": 2000 }
      },
      "additionalProperties": true
    },
    "label": {
      "type": "object",
      "required": ["id", "maker", "blend", "artworkAssetId", "surface", "writeInAreas", "research"],
      "properties": {
        "id": { "$ref": "#/$defs/canonicalId" },
        "maker": { "type": "string", "minLength": 1, "maxLength": 300 },
        "blend": { "type": "string", "minLength": 1, "maxLength": 300 },
        "displayName": { "type": "string", "minLength": 1, "maxLength": 300 },
        "artworkAssetId": { "$ref": "#/$defs/canonicalId" },
        "surface": { "$ref": "#/$defs/surface" },
        "writeInAreas": { "type": "array", "minItems": 1, "maxItems": 10, "items": { "$ref": "#/$defs/writeInArea" } },
        "research": { "$ref": "#/$defs/research" },
        "extensions": { "type": "object" }
      },
      "additionalProperties": true
    },
    "artworkAsset": {
      "type": "object",
      "required": ["path", "mediaType", "pixelWidth", "pixelHeight", "sha256", "colorSpace", "alpha"],
      "properties": {
        "path": { "type": "string", "pattern": "^artwork/[A-Za-z0-9._-]+\\.(?:png|jpe?g)$", "maxLength": 240 },
        "mediaType": { "enum": ["image/png", "image/jpeg"] },
        "pixelWidth": { "type": "integer", "minimum": 1, "maximum": 8192 },
        "pixelHeight": { "type": "integer", "minimum": 1, "maximum": 8192 },
        "sha256": { "type": "string", "pattern": "^[0-9a-f]{64}$" },
        "colorSpace": { "type": "string", "minLength": 1, "maxLength": 80 },
        "alpha": { "type": "boolean" }
      },
      "additionalProperties": true
    }
  }
}

